  $('adminButton').addEventListener('click',openAdmin);$('adminClose').addEventListener('click',closeAdmin);$('adminDialog').addEventListener('click',event=>{if(event.target===$('adminDialog'))closeAdmin()});document.querySelectorAll('.admin-tab').forEach(tab=>tab.addEventListener('click',()=>showAdminSection(tab.dataset.adminSection)));$('adminGeneralSave').addEventListener('click',saveAdminGeneral);$('adminPermissionsSave').addEventListener('click',saveAdminPermissions);$('adminPermissionMatrix').addEventListener('change',event=>{const input=event.target.closest('[data-role-permission]');if(input)input.nextElementSibling.textContent=input.checked?'Allowed':'Blocked'});$('adminUsersRefresh').addEventListener('click',()=>loadAdminUsers().catch(error=>setAdminMessage(error.message,true)));$('adminAuditRefresh').addEventListener('click',()=>loadAdminAudit().catch(error=>setAdminMessage(error.message,true)));$('adminListName').addEventListener('change',renderAdminList);$('adminListSave').addEventListener('click',saveAdminList);$('adminUserList').addEventListener('click',event=>{const button=event.target.closest('[data-admin-save]');if(button)saveAdminUser(Number(button.dataset.adminSave))});$('adminViewAdd').addEventListener('click',addAdminView);$('adminViewsSave').addEventListener('click',saveAdminViews);$('adminViewList').addEventListener('click',event=>{const button=event.target.closest('[data-view-remove]');if(button)removeAdminView(Number(button.dataset.viewRemove))});
