async function start(){
  config=await loadConfig();bindEvents();const legacyTheme=localStorage.getItem('uuuTT.theme');if(legacyTheme&&!localStorage.getItem('uuuTT.appearance'))localStorage.setItem('uuuTT.appearance',JSON.stringify({...defaultAppearance,mode:legacyTheme}));migrateCanonicalRowStyle();const query=new URLSearchParams(location.search),queryWorkspace=['tasks','dashboard','activity'].includes(query.get('workspace'))?query.get('workspace'):'tasks';applyAppearance();applyLanguage();
  if(config.dataMode!=='supabase'||!config.supabaseUrl||!config.supabasePublishableKey){repo=await createRepository(config);permissions={export:true};specialViews=await repo.getSpecialViews().then(rows=>rows.map(normalizeView));applyAppearance();$('connectionBadge').textContent='Demo mode';configureWriteUi();renderSummary(await repo.getSummary());await load(true);if(queryWorkspace!=='tasks')switchWorkspace(queryWorkspace);return}
  supabase=await createBrowserSupabase(config);const {data:{session:currentSession},error}=await supabase.auth.getSession();if(error)throw error;
  const listener=supabase.auth.onAuthStateChange((event,nextSession)=>{if(event==='SIGNED_IN'&&nextSession)setTimeout(()=>activateLive(nextSession).catch(async err=>{await supabase.auth.signOut();await activatePublic();openAuth(false);$('authMessage').textContent=err.message;$('authMessage').classList.add('error')}),0);if(event==='SIGNED_OUT')setTimeout(()=>activatePublic().catch(err=>toast(err.message)),0)});authSubscription=listener.data.subscription;
  if(currentSession)await activateLive(currentSession);else await activatePublic();
  if(query.get('settings-preview')==='1'&&['localhost','127.0.0.1'].includes(location.hostname)){permissions.settings=true;$('adminButton').hidden=false;await canonicalOpenAdmin()}
  else if(queryWorkspace!=='tasks')switchWorkspace(queryWorkspace)
}

window.addEventListener('pagehide',()=>authSubscription?.unsubscribe());
start().catch(error=>{console.error(error);$('connectionBadge').textContent='Connection error';$('taskList').innerHTML=`<div class="empty">${esc(error.message)}</div>`});

/* Canonical Settings parity layer. The legacy admin nodes remain hidden only to keep
   old event bindings safe while Settings is rendered from this single source. */
let canonicalAdminSection='general',canonicalSaveTimer=0;
const CANONICAL_LIST_DEFS=[{k:'priority',label:'Priority',color:true},{k:'status',label:'Status',color:true,group:true,dlabel:true},{k:'type',label:'Task Type'},{k:'platform',label:'Platform'},{k:'action',label:'Action Status'},{k:'progress',label:'Progress'},{k:'dept',label:'Department (Issued By)'},{k:'person',label:'Issued By — Person'},{k:'module',label:'Module'}];
const canonicalGeneral=()=>({appName:'Task Tracker',appSub:'UUU ERP Team',defaults:{priority:'',status:'Pending',type:'',platform:'UMS'},required:{title:false,priority:true,type:true,platform:true,menu:false,taskNo:false,issuedDept:false},pageSize:60,defaultLang:'bn',defaultAccent:'indigo',defaultMode:'system',defaultTint:'soft',defaultDensity:'comfortable',defaultSize:'md',defaultGroupStyle:'line',defaultMobileLayout:'summary',defaultMarkOn:'on',defaultMarkStatus:['Done'],defaultMarkPriority:['Urgent'],...(adminGeneral||{})});
function canonicalList(k){return (adminLists[k]||[]).map(item=>typeof item==='string'?{name:item,active:true}:{active:true,...item})}
function canonicalSetAdminMessage(message,error=false){const el=$('canonicalAdminMessage');if(!el)return;el.textContent=message;el.classList.toggle('error',error);el.hidden=!message}
function canonicalNav(k,label,n){return `<button class="nav-item${canonicalAdminSection===k?' active':''}" type="button" data-canonical-section="${k}"><span>${esc(label)}</span>${n==null?'':`<small>${n}</small>`}</button>`}
function renderCanonicalMenu(){const el=$('adminSettingsMenu');if(el)el.innerHTML=`<h6 style="margin:6px 10px">General</h6>${canonicalNav('general','App settings')}${canonicalNav('views','Special tabs',adminSpecialViews.length)}<h6 style="margin:12px 10px 6px">Option lists</h6>${CANONICAL_LIST_DEFS.map(d=>canonicalNav(d.k,d.label,canonicalList(d.k).length)).join('')}<h6 style="margin:12px 10px 6px">Access</h6>${canonicalNav('users','Users & roles',adminUsers.length)}${canonicalNav('permissions','Role permissions')}${canonicalNav('import','Import old tasks')}`}
function gSelect(field,values,current){return `<select data-cg="${field}">${values.map(([v,l])=>`<option value="${v}"${String(current)===String(v)?' selected':''}>${l}</option>`).join('')}</select>`}
function listSelect(field,k,current){return `<select data-cg="${field}"><option value="">— None —</option>${canonicalList(k).filter(x=>x.active).map(x=>`<option value="${esc(x.name)}"${x.name===current?' selected':''}>${esc(x.name)}</option>`).join('')}</select>`}
function canonicalGeneralPanel(){const g=canonicalGeneral(),d={priority:'',status:'Pending',type:'',platform:'UMS',...(g.defaults||{})},r={...(g.required||{})},chk=(key,label,locked=false)=>`<label class="chk${locked?' locked':''}"><input type="checkbox" data-cgr="${key}"${locked||r[key]?' checked':''}${locked?' disabled':''}>${label}</label>`,markers=(key,k,fallback)=>canonicalList(k).filter(x=>x.active).map(x=>`<label><input type="checkbox" data-cgm="${key}|${esc(x.name)}"${arrayValue(g[key]||fallback).includes(x.name)?' checked':''}>${esc(x.name)}</label>`).join('');return `<div class="set-head"><h3>App settings</h3><p>App name, default values for new tasks, required fields and display.</p></div><div class="gen-grid"><div class="gen-sec">Name & branding</div><div class="fg"><label>App name</label><input data-cg="appName" value="${esc(g.appName)}"></div><div class="fg"><label>Subtitle</label><input data-cg="appSub" value="${esc(g.appSub)}" placeholder="UUU ERP Team"><div class="hint">Leave blank to show the default text for the current language</div></div><div class="gen-sec">Default values for new tasks</div><div class="fg"><label>Priority</label>${listSelect('defaults.priority','priority',d.priority)}</div><div class="fg"><label>Status</label>${listSelect('defaults.status','status',d.status)}</div><div class="fg"><label>Task Type</label>${listSelect('defaults.type','type',d.type)}</div><div class="fg"><label>Platform</label>${listSelect('defaults.platform','platform',d.platform)}<div class="hint">These are pre-selected when the new-task form opens</div></div><div class="gen-sec">Required fields</div><div class="fg full"><div class="chk-list">${chk('status','Status',true)}${chk('details','Details',true)}${chk('priority','Priority')}${chk('type','Task Type')}${chk('platform','Platform')}${chk('title','Title')}${chk('menu','Menu')}${chk('taskNo','Task No. (Teams)')}${chk('issuedDept','Issued By — Department')}</div><div class="hint">Ticked fields must be filled before saving. Status and Details are always required.</div></div><div class="gen-sec">Display</div><div class="fg"><label>Tasks shown per batch</label>${gSelect('pageSize',[[30,'30'],[60,'60'],[100,'100'],[200,'200']],g.pageSize)}</div><div class="fg"><label>Default language</label>${gSelect('defaultLang',[['bn','বাংলা'],['en','English']],g.defaultLang)}<div class="hint">Language shown the first time the site is opened</div></div><div class="gen-sec">Default theme</div><div class="fg"><label>Color</label>${gSelect('defaultAccent',[['indigo','Indigo'],['blue','Blue'],['teal','Teal'],['green','Green'],['rose','Rose'],['orange','Orange'],['purple','Purple'],['slate','Slate']],g.defaultAccent)}</div><div class="fg"><label>Mode</label>${gSelect('defaultMode',[['light','Light'],['dark','Dark'],['system','System']],g.defaultMode)}</div><div class="fg"><label>Task color (by priority)</label>${gSelect('defaultTint',[['none','Stripe only'],['soft','Soft tint'],['fade','Left fade'],['frame','Color frame'],['urgent','Urgent only']],g.defaultTint)}</div><div class="fg"><label>Density</label>${gSelect('defaultDensity',[['comfortable','Comfortable'],['compact','Compact']],g.defaultDensity)}</div><div class="fg"><label>Text size</label>${gSelect('defaultSize',[['sm','Small'],['md','Normal'],['lg','Large']],g.defaultSize)}</div><div class="fg"><label>Group style</label>${gSelect('defaultGroupStyle',[['line','Header line'],['panel','Separate panel']],g.defaultGroupStyle)}</div><div class="fg"><label>Mobile layout</label>${gSelect('defaultMobileLayout',[['summary','New — summary card'],['classic','Classic — tiles']],g.defaultMobileLayout)}</div><div class="fg"><label>Side labels in the list (desktop)</label>${gSelect('defaultMarkOn',[['on','Show'],['off','Hide']],g.defaultMarkOn)}</div><div class="fg full"><label>Side label — Status</label><div class="mk-chips">${markers('defaultMarkStatus','status',['Done'])}</div></div><div class="fg full"><label>Side label — Priority</label><div class="mk-chips">${markers('defaultMarkPriority','priority',['Urgent'])}</div></div><div class="fg full"><div class="hint">Users who have not changed their theme see these. If someone changes only one thing, the rest still comes from here.</div></div></div>`}
function canonicalListPanel(k){const d=CANONICAL_LIST_DEFS.find(x=>x.k===k)||CANONICAL_LIST_DEFS[0],list=canonicalList(k);return `<div class="set-head"><h3>${esc(d.label)}</h3><p>Task form, filter ও report-এ ব্যবহৃত option-গুলো পরিচালনা করুন।</p></div>${list.map((o,i)=>`<div class="opt-row${d.color?'':' nocolor'}${d.group?' hasgroup':''}${o.active===false?' inactive':''}" data-cl="${k}" data-ci="${i}"><span class="ord"><button type="button" data-clmove="-1"${i?'':' disabled'}>▲</button><button type="button" data-clmove="1"${i<list.length-1?'':' disabled'}>▼</button></span>${d.color?`<input class="swatch" type="color" data-clcolor value="${esc(o.color||'#9CA3AF')}">`:''}${d.dlabel?`<div class="opt-names"><input class="opt-name" data-clname value="${esc(o.name)}"><label class="opt-lbl"><small>Label</small><input data-cllabel value="${esc(o.label||'')}" placeholder="${esc(o.name)}"></label></div>`:`<input class="opt-name" data-clname value="${esc(o.name)}">`}${d.group?`<select class="opt-group" data-clgroup>${[['open','Open'],['done','Done'],['other','Other']].map(([v,l])=>`<option value="${v}"${(o.group||'other')===v?' selected':''}>${l}</option>`).join('')}</select>`:''}<span class="opt-use">Used</span><label class="switch"><input type="checkbox" data-clactive${o.active===false?'':' checked'}><span class="sw-t">${o.active===false?'Inactive':'Active'}</span></label><button class="icon-del" type="button" data-cldelete aria-label="Delete">×</button></div>`).join('')}<div class="opt-add"><input id="canonicalOptionNew" placeholder="New ${esc(d.label)}"><button class="btn primary" type="button" data-cladd="${k}">＋ Add</button></div><div class="set-note">নাম, রং, order ও active state পরিবর্তন করলে সঙ্গে সঙ্গে save হবে। ব্যবহৃত option delete না করে inactive রাখুন।</div>`}
function canonicalUsersPanel(){const roles=['Admin','Editor','Viewer'];return `<div class="set-head"><h3>Users & roles</h3><p>Approved users, role and active access. নিজের Admin access বন্ধ করা যাবে না।</p></div>${adminUsers.map((u,i)=>`<div class="user-row"><span class="admin-avatar">${esc((u.display_name||u.email||'?').slice(0,1).toUpperCase())}</span><input value="${esc(u.display_name||u.email.split('@')[0])}" disabled><input class="u-email" value="${esc(u.email)}" disabled><select data-admin-role="${i}">${roles.map(role=>`<option${u.role===role?' selected':''}>${role}</option>`).join('')}</select><label class="switch"><input type="checkbox" data-admin-active="${i}"${u.is_active?' checked':''}><span class="sw-t">Active</span></label><button class="btn" type="button" data-admin-save="${i}">Save</button></div>`).join('')}<div class="set-note"><button class="btn" type="button" data-users-refresh>Refresh users</button></div>`}
function canonicalPermissionsPanel(){const acts=[['add','Add','Create new tasks'],['edit','Edit','Change task content'],['status','Status','Change task status'],['delete','Delete','Move tasks to Deleted'],['export','Export','Download XLSX'],['settings','Settings','Manage app settings']],roles=['Admin','Editor','Viewer'];return `<div class="set-head"><h3>Role permissions</h3><p>Admin সব permission পান। Editor ও Viewer-এর action access নির্ধারণ করুন। পরিবর্তন সঙ্গে সঙ্গে সেভ হবে।</p></div><table class="perm-table"><thead><tr><th>Action</th>${roles.map(r=>`<th>${r}</th>`).join('')}</tr></thead><tbody>${acts.map(([a,l,s])=>`<tr><td><b>${l}</b><small>${s}</small></td>${roles.map(role=>`<td><input type="checkbox" data-role-permission="${role}|${a}"${role==='Admin'||adminRolePermissions[role]?.[a]?' checked':''}${role==='Admin'?' disabled':''}></td>`).join('')}</tr>`).join('')}</tbody></table>`}
function canonicalViewsPanel(){const chips=(i,key,k)=>{const cur=arrayValue(adminSpecialViews[i]?.condition?.[key]||(key==='type'?adminSpecialViews[i]?.condition?.taskType:[]));return `<div class="fopts">${canonicalList(k).filter(x=>x.active).map(o=>`<button class="fopt${cur.includes(o.name)?' on':''}" type="button" data-vcond="${i}|${key}|${esc(o.name)}">${esc(o.name)}</button>`).join('')}</div>`};return `<div class="set-head"><h3>Special tabs</h3><p>এক বা একাধিক matching rule দিয়ে নিজের Task tab তৈরি করুন। নির্বাচিত rule-গুলো একসঙ্গে মিলতে হবে।</p></div><div class="canonical-views">${adminSpecialViews.map((v,i)=>`<div class="view-card" data-vi="${i}"><div class="vc-head"><input type="color" class="swatch" data-view-color="${i}" value="${esc(v.color)}" title="Color"><input class="opt-name" data-view-name="${i}" value="${esc(v.name)}" title="Tab name"><label class="switch"><input type="checkbox" data-view-active="${i}"${v.active?' checked':''}><span class="sw-t">Show</span></label><label class="switch"><input type="checkbox" data-view-tag="${i}"${v.tag?' checked':''}><span class="sw-t">Tag</span></label><button class="icon-del" type="button" data-view-remove="${i}" title="Delete">×</button></div><div class="vc-count">Matching rules</div><div class="vc-grid"><div><h5>Task Type</h5>${chips(i,'type','type')}</div><div><h5>Issued By — Department</h5>${chips(i,'dept','dept')}</div><div><h5>Issued By — Person / Approved By</h5><input class="vc-person" data-view-person="${i}" value="${esc(arrayValue(v.condition?.person).join(', '))}" placeholder="One or more names, comma separated"><div class="hint">Person rule Issued Person ও Approved By—দুটিতেই খোঁজে।</div></div><div><h5>Priority</h5>${chips(i,'priority','priority')}</div><div><h5>Platform</h5>${chips(i,'platform','platform')}</div></div></div>`).join('')}</div><div class="opt-add"><button class="btn primary" type="button" data-cvadd>＋ Add special tab</button><span class="grow"></span><button class="btn primary" type="button" data-cvsave>Save special tabs</button></div><div class="set-note">একাধিক section-এ option নিলে প্রতিটি section-এর অন্তত একটি value task-এর সঙ্গে মিলতে হবে।</div>`}
function canonicalImportPanel(){return `<div class="set-head"><h3>Import old tasks</h3><p>Google Sheet export থেকে পুরনো task যাচাই করে Supabase-এ import করুন।</p></div><div class="imp-body"><div class="imp-step"><h5><b>১</b> Import file নির্বাচন</h5><input type="file" accept=".json" disabled><div class="hint">Privileged browser import প্রস্তুত না হওয়া পর্যন্ত নিরাপত্তার জন্য disabled। Controlled import scripts ব্যবহার করুন।</div></div></div>`}
function renderAdminSettings(){renderCanonicalMenu();const el=$('adminSettingsPanel');if(el)el.innerHTML=canonicalAdminSection==='general'?canonicalGeneralPanel():canonicalAdminSection==='views'?canonicalViewsPanel():canonicalAdminSection==='users'?canonicalUsersPanel():canonicalAdminSection==='permissions'?canonicalPermissionsPanel():canonicalAdminSection==='import'?canonicalImportPanel():canonicalListPanel(canonicalAdminSection)}
function canonicalShowAdminSection(name){canonicalAdminSection=name;canonicalSetAdminMessage('');renderAdminSettings()}
async function canonicalOpenAdmin(){if(!permissions.settings)return;canonicalSetAdminMessage('');const panel=$('adminDialog').querySelector('.admin-panel');state.workspace='settings';$('tasksWorkspace').hidden=true;$('dashboardSection').hidden=true;$('activitySection').hidden=true;$('settingsSection').hidden=false;$('settingsSection').append(panel);document.querySelectorAll('[data-workspace]').forEach(button=>button.classList.remove('active'));$('adminButton').classList.add('active');window.scrollTo(0,0);renderAdminSettings();try{await Promise.all([loadAdminGeneral(),loadAdminUsers(),loadAdminLists(),loadAdminViews(),loadAdminPermissions()]);renderAdminSettings()}catch(error){canonicalSetAdminMessage(error.message||'Settings data load করা যায়নি',true)}}
function readCanonicalGeneral(){const next=structuredClone(canonicalGeneral());document.querySelectorAll('[data-cg]').forEach(el=>{const p=el.dataset.cg;if(p.startsWith('defaults.'))next.defaults[p.split('.')[1]]=el.value;else next[p]=p==='pageSize'?Number(el.value):el.value});document.querySelectorAll('[data-cgr]').forEach(el=>next.required[el.dataset.cgr]=el.checked);['defaultMarkStatus','defaultMarkPriority'].forEach(k=>next[k]=[...document.querySelectorAll(`[data-cgm^="${k}|"]:checked`)].map(el=>el.dataset.cgm.split('|').slice(1).join('|')));return next}
async function saveCanonicalGeneral(){canonicalSetAdminMessage('Save হচ্ছে…');try{adminGeneral=await repo.updateAdminGeneral(readCanonicalGeneral());canonicalSetAdminMessage('App settings আপডেট হয়েছে');toast('App settings আপডেট হয়েছে')}catch(error){canonicalSetAdminMessage(error.message||'App settings update করা যায়নি',true)}}
function readCanonicalList(k){return [...document.querySelectorAll(`[data-cl="${k}"]`)].map(row=>({name:row.querySelector('[data-clname]').value.trim(),active:row.querySelector('[data-clactive]').checked,...(row.querySelector('[data-clcolor]')?{color:row.querySelector('[data-clcolor]').value}:{}),...(row.querySelector('[data-clgroup]')?{group:row.querySelector('[data-clgroup]').value}:{}),...(row.querySelector('[data-cllabel]')?.value.trim()?{label:row.querySelector('[data-cllabel]').value.trim()}: {})})).filter(x=>x.name)}
async function persistCanonicalList(k,items=readCanonicalList(k)){canonicalSetAdminMessage('Save হচ্ছে…');try{await repo.updateAdminList(k,items);adminLists[k]=items;formOptions=await repo.getOptions();configureWriteUi();renderCanonicalMenu();canonicalSetAdminMessage(`${CANONICAL_LIST_DEFS.find(d=>d.k===k)?.label||k} list আপডেট হয়েছে`)}catch(error){canonicalSetAdminMessage(error.message||'List update করা যায়নি',true)}}
async function canonicalSaveAdminPermissions(){const next={Editor:{},Viewer:{}},root=$('canonicalSettings');root.querySelectorAll('[data-role-permission]').forEach(el=>{const [r,a]=el.dataset.rolePermission.split('|');if(next[r])next[r][a]=el.checked});canonicalSetAdminMessage('Save হচ্ছে…');try{adminRolePermissions=await repo.updateAdminPermissions(next);canonicalSetAdminMessage('Role permissions আপডেট হয়েছে');toast('Role permissions আপডেট হয়েছে')}catch(error){canonicalSetAdminMessage(error.message||'Role permissions update করা যায়নি',true)}}
async function canonicalSaveAdminUser(index){const user=adminUsers[index],root=$('canonicalSettings'),button=root.querySelector(`[data-admin-save="${index}"]`),role=root.querySelector(`[data-admin-role="${index}"]`).value,isActive=root.querySelector(`[data-admin-active="${index}"]`).checked;button.disabled=true;canonicalSetAdminMessage('Save হচ্ছে…');try{await repo.updateAdminUser(user.email,role,isActive);canonicalSetAdminMessage(`${user.email} আপডেট হয়েছে`);await loadAdminUsers();renderAdminSettings();toast(`${user.email} আপডেট হয়েছে`)}catch(error){canonicalSetAdminMessage(error.message||'User update করা যায়নি',true)}finally{button.disabled=false}}
function canonicalAddAdminView(){adminSpecialViews.push(normalizeView({id:`view_${Date.now()}`,name:'New Tab',color:'#7C3AED',active:true,tag:true,condition:{taskType:['Our Task']}},adminSpecialViews.length));renderAdminSettings()}
function canonicalRemoveAdminView(index){adminSpecialViews.splice(index,1);renderAdminSettings()}
async function canonicalSaveAdminViews(){const root=$('canonicalSettings'),next=adminSpecialViews.map((view,index)=>{const condition={};['type','dept','priority','platform'].forEach(key=>{const values=[...root.querySelectorAll(`[data-vcond^="${index}|${key}|"]`).values()].filter(el=>el.classList.contains('on')).map(el=>el.dataset.vcond.split('|').slice(2).join('|'));if(values.length)condition[key]=values});const people=root.querySelector(`[data-view-person="${index}"]`).value.split(',').map(value=>value.trim()).filter(Boolean);if(people.length)condition.person=people;return {id:view.id,name:root.querySelector(`[data-view-name="${index}"]`).value.trim(),color:root.querySelector(`[data-view-color="${index}"]`).value,active:root.querySelector(`[data-view-active="${index}"]`).checked,tag:root.querySelector(`[data-view-tag="${index}"]`).checked,condition}});if(next.some(view=>!view.name||!Object.values(view.condition).some(values=>values.length))){canonicalSetAdminMessage('প্রতিটি Special Tab-এর Name ও অন্তত একটি matching rule দিন।',true);return}canonicalSetAdminMessage('Save হচ্ছে…');try{await repo.updateAdminSpecialViews(next);specialViews=next.map(normalizeView);adminSpecialViews=next.map(normalizeView);renderSpecialTabs();renderAdminSettings();canonicalSetAdminMessage('Special Tabs আপডেট হয়েছে');toast('Special Tabs আপডেট হয়েছে');if(state.workspace==='tasks')await load(true)}catch(error){canonicalSetAdminMessage(error.message||'Special Tabs update করা যায়নি',true)}}
function bindCanonicalSettingsEvents(){const root=$('canonicalSettings');if(!root)return;$('adminButton').addEventListener('click',canonicalOpenAdmin);$('canonicalAdminClose').addEventListener('click',closeAdmin);root.addEventListener('click',event=>{const nav=event.target.closest('[data-canonical-section]');if(nav){canonicalShowAdminSection(nav.dataset.canonicalSection);return}const condition=event.target.closest('[data-vcond]');if(condition){condition.classList.toggle('on');return}const row=event.target.closest('[data-cl]');if(event.target.closest('[data-cldelete]')&&row){const k=row.dataset.cl,items=readCanonicalList(k);items.splice(Number(row.dataset.ci),1);adminLists[k]=items;renderAdminSettings();persistCanonicalList(k,items);return}const move=event.target.closest('[data-clmove]');if(move&&row){const k=row.dataset.cl,items=readCanonicalList(k),i=Number(row.dataset.ci),j=i+Number(move.dataset.clmove);[items[i],items[j]]=[items[j],items[i]];adminLists[k]=items;renderAdminSettings();persistCanonicalList(k,items);return}const add=event.target.closest('[data-cladd]');if(add){const k=add.dataset.cladd,input=$('canonicalOptionNew'),name=input.value.trim();if(!name)return;const items=canonicalList(k);items.push({name,active:true,...(CANONICAL_LIST_DEFS.find(d=>d.k===k)?.color?{color:'#9CA3AF'}:{}),...(k==='status'?{group:'open'}:{})});adminLists[k]=items;renderAdminSettings();persistCanonicalList(k,items);return}const user=event.target.closest('[data-admin-save]');if(user){canonicalSaveAdminUser(Number(user.dataset.adminSave));return}if(event.target.closest('[data-users-refresh]'))loadAdminUsers().then(renderAdminSettings).catch(e=>canonicalSetAdminMessage(e.message,true));if(event.target.closest('[data-cvadd]'))canonicalAddAdminView();if(event.target.closest('[data-cvsave]'))canonicalSaveAdminViews();const remove=event.target.closest('[data-view-remove]');if(remove)canonicalRemoveAdminView(Number(remove.dataset.viewRemove))});root.addEventListener('change',event=>{if(event.target.matches('[data-cg],[data-cgr],[data-cgm]')){clearTimeout(canonicalSaveTimer);canonicalSaveTimer=setTimeout(saveCanonicalGeneral,450);return}if(event.target.matches('[data-role-permission]')){clearTimeout(canonicalSaveTimer);canonicalSaveTimer=setTimeout(canonicalSaveAdminPermissions,350);return}const row=event.target.closest('[data-cl]');if(row){clearTimeout(canonicalSaveTimer);canonicalSaveTimer=setTimeout(()=>persistCanonicalList(row.dataset.cl),450)}});root.addEventListener('focusout',event=>{const row=event.target.closest('[data-cl]');if(row){clearTimeout(canonicalSaveTimer);canonicalSaveTimer=setTimeout(()=>persistCanonicalList(row.dataset.cl),450)}else if(event.target.matches('[data-cg]')){clearTimeout(canonicalSaveTimer);canonicalSaveTimer=setTimeout(saveCanonicalGeneral,450)}})}
bindCanonicalSettingsEvents();
$('adminButton').removeEventListener('click',openAdmin);
